diff --git a/lib/src/cli/agent_cli_compaction.dart b/lib/src/cli/agent_cli_compaction.dart
index 4e6d480a6f..81d55dbafd 100644
--- a/lib/src/cli/agent_cli_compaction.dart
+++ b/lib/src/cli/agent_cli_compaction.dart
@@ -320,12 +320,25 @@ List<String> formatCompactionReport(
     if (summary != null && summary.isNotEmpty) ...[
       'summary:',
       '```',
-      summary,
+      _balanceSummaryFences(summary),
       '```',
     ],
   ];
 }

+/// gh-1755: balances unclosed code fences in compaction summaries so the
+/// outer closing fence does not toggle markdown rendering into verbatim
+/// code (an LLM summary that ends mid-fence used to swallow every row
+/// the report rendered after it).
+String _balanceSummaryFences(String summary) {
+  final fencePattern = RegExp(r'^\s*```');
+  final fenceCount = summary.split('\n').where(fencePattern.hasMatch).length;
+  if (fenceCount.isOdd) {
+    return '$summary\n```';
+  }
+  return summary;
+}
+
 /// Renders [formatCompactionReport] through the styled transcript writer
 /// so both line mode and the TUI see the same block.
 extension _AgentCliCompactionReportPrinter on AgentCli {
diff --git a/lib/src/cli/ansi_markdown.dart b/lib/src/cli/ansi_markdown.dart
index d0449f8804..76c6dcc478 100644
--- a/lib/src/cli/ansi_markdown.dart
+++ b/lib/src/cli/ansi_markdown.dart
@@ -221,7 +221,7 @@ final class AnsiMarkdown {
       return '$_dim${'─' * width}$_reset';
     }

-    final fenced = _formatFence(line);
+    final fenced = _formatFence(line, stripped);
     if (fenced != null) return fenced;

     return _formatMarkdownLine(line);
@@ -278,10 +278,21 @@ final class AnsiMarkdown {
   /// Code fences swallow everything between the markers verbatim (pi:
   /// content indented 2 spaces, no background, dim border lines). Null for
   /// markdown content outside a fence.
-  String? _formatFence(String line) {
-    if (_fenceRe.hasMatch(line)) {
+  String? _formatFence(String line, [String? stripped]) {
+    // gh-1755: regex-test the ANSI-STRIPPED text — a fence line carrying
+    // SGR bytes (e.g. the compaction report's dimmed ```) fails _fenceRe
+    // on the raw line, the fence state never latches, and every row after
+    // an unbalanced fence renders verbatim. When the raw line already IS
+    // the text (no escapes), dim as before; otherwise the caller-styled
+    // bytes stand — re-dimming would stack SGR (no double-styling).
+    final text =
+        stripped ??
+        (line.codeUnits.any((c) => c == 0x1b)
+            ? line.replaceAll(_ansiRe, '')
+            : line);
+    if (_fenceRe.hasMatch(text)) {
       _inFence = !_inFence;
-      return '$_dim$line$_reset';
+      return text == line ? '$_dim$line$_reset' : line;
     }
     if (_inFence) {
       return '  $line';
diff --git a/test/cli/tui_compaction_render_regression_test.dart b/test/cli/tui_compaction_render_regression_test.dart
new file mode 100644
index 0000000000..2cc476d5df
--- /dev/null
+++ b/test/cli/tui_compaction_render_regression_test.dart
@@ -0,0 +1,158 @@
+// Regression (issue #1755, ledger #13): the TUI transcript must keep
+// thinking and answer text separate and untruncated across an
+// auto-compaction. The compaction report wraps the LLM summary in a ```
+// fence; a summary whose own fence lines are unbalanced used to leave the
+// transcript formatter inside an open code fence, so every answer row
+// after the report rendered verbatim (raw `**`, `#` headings) — the
+// "garbled after auto-compaction" symptom. Root cause: `_formatFence`
+// regex-tested the RAW line, so a fence line carrying SGR bytes (the
+// report dims its fences at print time) failed `_fenceRe` and the fence
+// state never latched. Fix origin: YuryBY's `fix/tui-compaction-summary-fence`
+// (closed PR #1747, commit 7557efeeb) — re-landed here.
+library;
+
+import 'package:flutter_agent_harness/flutter_agent_harness.dart';
+import 'package:flutter_agent_harness/src/cli/ansi_markdown.dart';
+import 'package:test/test.dart';
+
+/// The TUI transcript lines a run produced: a dimmed thinking row, the
+/// answer, then the compaction report (split on newlines the way the output
+/// history stores it), then the post-compaction answer. The report's ```
+/// lines carry the dim SGR the printer bakes in (`agent_cli_compaction.dart`
+/// prints `line == '```' ? _style.dim(line) : line`).
+List<String> _transcript(String summary) {
+  final pass = AutoCompactorPass(
+    pass: 1,
+    tokensBefore: 104717,
+    tokensAfter: 43430,
+    fallback: 'structured',
+    ok: true,
+    summary: summary,
+    hiddenRecords: 12,
+    summarizedMessages: 9,
+  );
+  return [
+    '\x1b[2mthinking about the plan\x1b[0m',
+    'Answer **before** compaction',
+    for (final line in formatCompactionReport(pass, auto: true, details: true))
+      ...line.split('\n').map((p) => p == '```' ? '\x1b[2m```\x1b[0m' : p),
+    'Answer **after** compaction',
+    '# Heading after',
+  ];
+}
+
+void main() {
+  group('TUI transcript across auto-compaction (issue #1755)', () {
+    test(
+      'a summary with unbalanced ``` fences does not swallow the rows after it',
+      () {
+        final tx = TranscriptMarkdown(width: 80)
+          ..sync(_transcript('Goal.\n```py\nprint(1)'));
+        final rows = tx.wrappedRows.map((r) => r.replaceAll('\x1b', 'E'));
+        // AC1: the post-compaction answer renders as markdown (bold SGR),
+        // not as verbatim code with the raw `**` markers.
+        expect(
+          rows.any((r) => r.contains('E[1m') && r.contains('after')),
+          isTrue,
+          reason: rows.join('\n'),
+        );
+        expect(rows.any((r) => r.contains('**after**')), isFalse);
+        expect(rows.any((r) => r.contains('# Heading after')), isFalse);
+      },
+    );
+
+    test('thinking rows and the answer stay on separate rows', () {
+      final tx = TranscriptMarkdown(width: 80)
+        ..sync(_transcript('Goal.\n```py\nprint(1)'));
+      final rows = tx.wrappedRows;
+      final thinking = rows.indexWhere((r) => r.contains('thinking about'));
+      final answer = rows.indexWhere((r) => r.contains('before'));
+      expect(thinking, isNonNegative);
+      expect(answer, greaterThan(thinking));
+      expect(
+        rows[answer].contains('thinking about'),
+        isFalse,
+        reason: rows.join('\n'),
+      );
+    });
+
+    test(
+      'styled fence lines still latch fences without double-styling (AC2)',
+      () {
+        final md = AnsiMarkdown();
+        final styled = '\x1b[2m```\x1b[0m';
+        // A fence line carrying SGR bytes is recognized as a fence (state
