  int? _runTokensBefore;

  @override
  void onDone(int passes, int tokens) {
    if (passes > 0) {
      cli._logDiagnostic('auto-compact done passes=$passes tokens=$tokens');
    }
    // Backend agent mode (issue #155): close the compaction bracket once
